// ─────────────────────────────────────────────────────────────────────────
//  01 · one CSV line★★☆ core
//  concepts: StringBuilder · RFC 4180 escaping
// ─────────────────────────────────────────────────────────────────────────
//
//  Quote only the fields that need it; double every quote inside them.

using static Bootcamp.Check;

string CsvLine(IEnumerable<string?> fields)
{
    var sb = new System.Text.StringBuilder();
    var first = true;
    foreach (var field in fields)
    {
        if (!first) sb.Append(',');
        first = false;
        var f = field ?? "";
        if (f.IndexOfAny(new[] { ',', '"', '\r', '\n' }) >= 0) sb.Append('"').Append(f.Replace("\"", "\"\"")).Append('"');
        else sb.Append(f);
    }
    return sb.ToString();
}

// ──────────────────────────── tests ──────────────────────────────────────

Test("plain fields are joined with commas", () =>
    Eq(CsvLine(new[] { "a", "b", "c" }), "a,b,c"));

Test("commas and quotes are escaped", () =>
    Eq(CsvLine(new[] { "Pen", "Ink, blue", "5\" ruler" }), "Pen,\"Ink, blue\",\"5\"\" ruler\""));

Test("line breaks force quoting", () =>
    Eq(CsvLine(new[] { "line1\nline2", "x\ry" }), "\"line1\nline2\",\"x\ry\""));

Test("null is an empty field, spaces are kept", () =>
    Eq(CsvLine(new[] { null, " padded ", "" }), ", padded ,"));

Test("no fields gives an empty line (boundary)", () =>
    Eq(CsvLine(Array.Empty<string?>()), ""));

fund-csharp/03-strings-and-formatting/01.explanation:
Decide per field whether it needs quoting, and build the line once:

```csharp
var f = field ?? "";
if (f.IndexOfAny(new[] { ',', '"', '\r', '\n' }) >= 0)
    sb.Append('"').Append(f.Replace("\"", "\"\"")).Append('"');
else
    sb.Append(f);
```

Quoting every field would also be valid CSV but fails the exact-output tests here; forgetting to double the inner quotes makes Excel end the field early.
